function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(100 + i * 100 + 50 * Math.cos(t + i), 100 + 20 * Math.sin(t + i), 20 + 10 * Math.sin(t + i), 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // mountains
  ctx.fillStyle = 'gray';
  ctx.beginPath();
  ctx.moveTo(0, H);
  ctx.lineTo(W / 2 + 100 * Math.sin(t), H - 100 - 50 * Math.sin(t));
  ctx.lineTo(W, H);
  ctx.fill();
  ctx.stroke();

  // trees
  ctx.fillStyle = 'green';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(200 + i * 100, H - 50 - 20 * Math.sin(t + i), 10 + 5 * Math.sin(t + i), 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(200 + i * 100, H - 50 - 20 * Math.sin(t + i));
    ctx.lineTo(200 + i * 100, H);
    ctx.stroke();
  }

  ctx.restore();
}
